// Previous prototype retained as a scratch reference during the layout update.
(() => {
  const screen=document.querySelector('#flow-screen'), dialog=document.querySelector('#instructions');
  const layouts={classic:{name:'The classic',count:4,rows:4,cols:1,note:'4 photos · 4 rows'},mini:{name:'The little one',count:2,rows:2,cols:1,note:'2 photos · 2 rows'},grid:{name:'The whole story',count:6,rows:3,cols:2,note:'6 photos · 3 rows'}};
  const filters={original:'none',mono:'grayscale(1)',vintage:'sepia(.48) saturate(.7) contrast(.93)',rose:'sepia(.2) saturate(.75) hue-rotate(320deg)'};
  const colors={cherry:['#a82e3e','#fff7ec'],cream:['#faf6ea','#262a27'],ink:['#292b2a','#faf6ea'],blue:['#c1d6e3','#262a27']};
  const state={step:'layout',layout:'classic',shots:[],filter:'original',color:'cherry',design:'classic',caption:'better together.',mode:'sample',stream:null,busy:false,generation:0};
  let timer,active=false,renderVersion=0,cameraRequest=0,exporting=false;
  const $=s=>screen.querySelector(s);
  const escape=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function heading(kicker,title,note){return `<div class="flow-heading"><div class="eyebrow">${kicker}</div><h1 tabindex="-1">${title}</h1><p>${note}</p></div>`}
  function stopCamera(){cameraRequest++;state.stream?.getTracks().forEach(t=>t.stop());state.stream=null;state.mode='sample'}
  function cancelCapture(){clearTimeout(timer);state.generation++;state.busy=false}
  function showStep(step){cancelCapture();state.step=step;document.querySelectorAll('[data-step]').forEach(el=>{const current=el.dataset.step===step;el.classList.toggle('current',current);current?el.setAttribute('aria-current','step'):el.removeAttribute('aria-current')});({layout:layoutScreen,session:sessionScreen,edit:editorScreen})[step]();screen.querySelector('h1')?.focus({preventScroll:true});window.scrollTo(0,0)}
  function miniature(layout){return `<span class="layout-mini" style="--columns:${layout.cols}">${Array.from({length:layout.count},()=>'<i></i>').join('')}<span>together.</span></span>`}
  function layoutScreen(){screen.innerHTML=heading('FIRST, A LITTLE SHAPE','Every memory needs <em>a frame.</em>','Choose the layout for your photocard. You’ll style it after the photos.')+`<fieldset class="layout-picker"><legend class="sr-only">Photocard layout</legend>${Object.entries(layouts).map(([key,l])=>`<label class="layout-option"><input type="radio" name="layout" value="${key}" ${state.layout===key?'checked':''}><span class="layout-choice">${miniature(l)}<strong>${l.name}</strong><span>${l.note}</span><span class="layout-check" aria-hidden="true">✓</span></span></label>`).join('')}</fieldset><div class="step-actions"><p>A tiny strip or the whole story. It’s up to you.</p><button class="primary" id="start-session">Into the booth <span aria-hidden="true">↗</span></button></div>`;screen.querySelectorAll('[name=layout]').forEach(r=>r.onchange=()=>{state.layout=r.value});$('#start-session').onclick=()=>{state.shots=[];showStep('session')}}
  function sessionScreen(){const l=layouts[state.layout];screen.innerHTML=heading('NOW, YOUR LITTLE MOMENT','A smile. A silly face. <em>You.</em>',`${l.name} · ${l.note}. Three seconds to get ready for each shot.`)+`<div class="session-surface"><div class="session-bar"><span id="session-mode">${state.mode==='camera'?'Solo camera session':'Sample session'}</span><button class="text-button" id="camera-toggle">${state.mode==='camera'?'Use sample photos':'Turn camera on'}</button></div><div class="session-view"><div class="sample-pair" ${state.mode==='camera'?'hidden':''}><img src="public/woman.jpg" alt="Sample portrait"><img src="public/man.jpg" alt="Sample portrait"></div><video id="live-camera" autoplay muted playsinline ${state.mode==='camera'?'':'hidden'}></video><div id="shot-countdown" hidden aria-live="assertive"></div></div><p id="camera-message" class="session-note" role="status">${state.mode==='camera'?'Camera on. Photos stay in this browser tab.':'Try the flow with sample portraits, or turn on your camera for real solo photos.'}</p><div class="shot-progress" aria-label="Captured photos">${Array.from({length:l.count},(_,i)=>`<span class="shot-slot ${state.shots[i]?'filled':''}">${state.shots[i]?`<img src="${state.shots[i]}" alt="Photo ${i+1}">`:String(i+1).padStart(2,'0')}</span>`).join('')}</div><p id="session-status" aria-live="polite">${state.shots.length} of ${l.count} photos ready</p><div class="session-buttons"><button class="text-button" id="change-layout">← Change layout</button><button class="primary" id="capture-session">${state.shots.length===l.count?'Retake all photos':'Start the countdown'} <span aria-hidden="true">◎</span></button><button class="secondary" id="to-editor" ${state.shots.length===l.count?'':'disabled'}>Make it yours →</button></div></div>`;if(state.stream)$('#live-camera').srcObject=state.stream;$('#camera-toggle').onclick=toggleCamera;$('#change-layout').onclick=()=>{stopCamera();showStep('layout')};$('#capture-session').onclick=startCapture;$('#to-editor').onclick=()=>{if(state.shots.length===l.count){stopCamera();showStep('edit')}}}
  async function toggleCamera(){if(state.stream){stopCamera();sessionScreen();return}const request=++cameraRequest;$('#camera-toggle').disabled=true;$('#capture-session').disabled=true;$('#camera-message').textContent='Waiting for camera permission…';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('unavailable');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});if(request!==cameraRequest||!active||state.step!=='session'){stream.getTracks().forEach(t=>t.stop());return}state.stream=stream;state.mode='camera';sessionScreen()}catch(e){if(request!==cameraRequest||state.step!=='session')return;$('#camera-message').textContent=e.name==='NotAllowedError'?'Camera permission was not granted. You can try again or continue with sample photos.':'The camera isn’t available. Check that it’s connected and not in use, or try sample photos.';$('#camera-toggle').disabled=false;$('#capture-session').disabled=false}}
  const loadImage=src=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src});
  function cover(ctx,img,x,y,w,h){const iw=img.videoWidth||img.naturalWidth,ih=img.videoHeight||img.naturalHeight;const scale=Math.max(w/iw,h/ih);ctx.drawImage(img,(iw-w/scale)/2,(ih-h/scale)/2,w/scale,h/scale,x,y,w,h)}
  async function takeShot(){const canvas=document.createElement('canvas');canvas.width=960;canvas.height=640;const ctx=canvas.getContext('2d');if(state.mode==='camera'){const video=$('#live-camera');if(!video?.videoWidth)throw Error('Camera is still warming up. Try the countdown again.');ctx.translate(960,0);ctx.scale(-1,1);cover(ctx,video,0,0,960,640)}else{const images=await Promise.all([loadImage('public/woman.jpg'),loadImage('public/man.jpg')]);cover(ctx,images[0],0,0,478,640);cover(ctx,images[1],482,0,478,640)}return canvas.toDataURL('image/jpeg',.94)}
  function startCapture(){if(state.busy)return;state.shots=[];state.busy=true;const generation=++state.generation;screen.querySelectorAll('button').forEach(b=>b.disabled=true);const l=layouts[state.layout];let n=3;const countdown=$('#shot-countdown');screen.querySelectorAll('.shot-slot').forEach((slot,i)=>{slot.classList.remove('filled');slot.textContent=String(i+1).padStart(2,'0')});function tick(){if(generation!==state.generation)return;countdown.hidden=false;countdown.textContent=n;$('#session-status').textContent=`Get ready for photo ${state.shots.length+1} of ${l.count}`;if(n>0){n--;timer=setTimeout(tick,1000)}else{countdown.textContent='♡';takeShot().then(shot=>{if(generation!==state.generation)return;state.shots.push(shot);const slot=screen.querySelectorAll('.shot-slot')[state.shots.length-1];slot.classList.add('filled');slot.innerHTML=`<img src="${shot}" alt="Photo ${state.shots.length}">`;if(state.shots.length===l.count){state.busy=false;sessionScreen();$('#session-status').textContent='All photos are ready. Retake them, or head to the editor.';$('#to-editor').focus()}else{n=3;timer=setTimeout(tick,600)}}).catch(e=>{if(generation!==state.generation)return;state.busy=false;sessionScreen();$('#camera-message').textContent=e.message})}}tick()}
  function editorScreen(){const l=layouts[state.layout];screen.innerHTML=heading('FINALLY, MAKE IT YOURS','A little keepsake. <em>All you.</em>',`${l.note}, just as you chose. Add the finishing touches.`)+`<div class="finish-grid"><div class="final-preview"><img id="card-preview" alt="Your photocard preview"><p id="preview-status" role="status">Preparing your photocard…</p></div><div class="finish-controls"><fieldset><legend>FRAME DESIGN</legend><div class="design-options">${[['classic','Classic'],['outline',l.cols===2?'Gallery border':'Double border'],['hearts',l.cols===2?'Love notes':'Little hearts']].map(([key,name])=>`<label><input type="radio" name="design" value="${key}" ${state.design===key?'checked':''}><span>${name}</span></label>`).join('')}</div></fieldset><fieldset><legend>FRAME COLOR</legend><div class="swatches">${Object.entries(colors).map(([key,c])=>`<button class="swatch ${state.color===key?'active':''}" data-color="${key}" aria-label="${key}" aria-pressed="${state.color===key}" style="--swatch:${c[0]}"></button>`).join('')}</div></fieldset><fieldset><legend>PHOTO FILTER</legend><div class="filter-options">${Object.keys(filters).map(key=>`<button class="filter ${state.filter===key?'active':''}" data-filter="${key}" aria-pressed="${state.filter===key}">${{original:'Original',mono:'Black & white',vintage:'Vintage',rose:'Rose'}[key]}</button>`).join('')}</div></fieldset><label class="caption-label" for="card-caption">A FEW WORDS TO KEEP</label><input id="card-caption" maxlength="28" value="${escape(state.caption)}"><p class="session-note">Your frame design adapts to your ${l.cols===2?'six-photo grid':'photo strip'}. Filters apply to every photo.</p><button class="text-button" id="back-session">← Back to your photos</button></div></div><div class="finish-bottom"><div><strong>Keep this little moment.</strong><p>Download a PNG or JPG, or open your browser’s print dialog.</p></div><div class="finish-buttons"><button class="outline-button" id="print-card">Print <span aria-hidden="true">↗</span></button><label class="sr-only" for="export-format">Download format</label><select id="export-format"><option value="png">PNG</option><option value="jpeg">JPG</option></select><button class="primary" id="download-card">Download <span aria-hidden="true">↓</span></button></div><p id="export-status" role="status"></p></div>`;
    screen.querySelectorAll('[name=design]').forEach(r=>r.onchange=()=>{state.design=r.value;updatePreview()});
    for(const type of ['color','filter'])screen.querySelectorAll(`[data-${type}]`).forEach(b=>b.onclick=()=>{state[type]=b.dataset[type];screen.querySelectorAll(`[data-${type}]`).forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b))});updatePreview()});
    $('#card-caption').oninput=e=>{state.caption=e.target.value;updatePreview()};$('#back-session').onclick=()=>showStep('session');$('#download-card').onclick=()=>exportCard(false);$('#print-card').onclick=()=>exportCard(true);updatePreview();
  }
  async function renderCard(){const snapshot={...state,shots:[...state.shots]},l=layouts[snapshot.layout],cellW=600,cellH=400,pad=40,gap=24,top=90,bottom=170;const canvas=document.createElement('canvas');canvas.width=pad*2+cellW*l.cols+gap*(l.cols-1);canvas.height=top+cellH*l.rows+gap*(l.rows-1)+bottom;const ctx=canvas.getContext('2d'),[bg,fg]=colors[snapshot.color];const images=await Promise.all(snapshot.shots.map(loadImage));await document.fonts.ready;ctx.fillStyle=bg;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle=fg;ctx.font='500 22px "DM Sans", Arial';ctx.fillText('T O G E T H E R',pad,52);ctx.textAlign='right';ctx.fillText(String(l.count).padStart(2,'0')+' MOMENTS',canvas.width-pad,52);images.forEach((img,i)=>{const x=pad+(i%l.cols)*(cellW+gap),y=top+Math.floor(i/l.cols)*(cellH+gap);ctx.save();ctx.filter=filters[snapshot.filter];cover(ctx,img,x,y,cellW,cellH);ctx.restore();if(snapshot.design==='outline'){ctx.strokeStyle=fg;ctx.lineWidth=3;ctx.strokeRect(x-8,y-8,cellW+16,cellH+16)}});ctx.fillStyle=fg;ctx.textAlign='center';let fontSize=70;ctx.font=`italic ${fontSize}px "Instrument Serif", Georgia`;while(ctx.measureText(snapshot.caption).width>canvas.width-100&&fontSize>20){fontSize--;ctx.font=`italic ${fontSize}px "Instrument Serif", Georgia`}ctx.fillText(snapshot.caption,canvas.width/2,canvas.height-80);ctx.font='16px "DM Sans", Arial';ctx.fillText('A LITTLE KEEPSAKE. A LOT OF LOVE.',canvas.width/2,canvas.height-37);if(snapshot.design==='hearts'){ctx.font='30px Georgia';ctx.fillText('♡',canvas.width/2,canvas.height-125)}return canvas}
  async function updatePreview(){const version=++renderVersion;try{const canvas=await renderCard();if(version!==renderVersion||state.step!=='edit')return;$('#card-preview').src=canvas.toDataURL('image/png');$('#preview-status').textContent='Your preview matches your download.'}catch{if(state.step==='edit')$('#preview-status').textContent='We couldn’t render the preview. Please go back and try your photos again.'}}
  async function exportCard(print){if(exporting)return;exporting=true;const status=$('#export-status');$('#download-card').disabled=$('#print-card').disabled=true;status.textContent=print?'Preparing your print…':'Preparing your download…';try{const canvas=await renderCard();if(print){const sheet=document.querySelector('#print-sheet');const img=new Image();img.alt='Your finished Together photocard';img.src=canvas.toDataURL('image/png');await img.decode();sheet.replaceChildren(img);window.print();status.textContent='Print dialog requested. Choose your printer or save as PDF.'}else{const format=$('#export-format').value;const blob=await new Promise(resolve=>canvas.toBlob(resolve,`image/${format}`,.95));if(!blob)throw Error();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`together-${layouts[state.layout].count}-photos.${format==='jpeg'?'jpg':'png'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Your photocard is ready to keep.'}}catch{status.textContent='Something went wrong. Please try again.'}finally{exporting=false;if(state.step==='edit')$('#download-card').disabled=$('#print-card').disabled=false}}
  function showInstructions(){if(state.busy){cancelCapture();sessionScreen()}if(!dialog.open)dialog.showModal()}
  document.querySelector('#show-instructions').onclick=showInstructions;
  document.querySelector('.dialog-close').onclick=()=>{dialog.close();if(state.step==='layout')location.hash=''};
  document.querySelector('#instructions-continue').onclick=()=>{dialog.close();screen.querySelector('h1')?.focus({preventScroll:true})};
  dialog.addEventListener('cancel',()=>{if(state.step==='layout')location.hash=''});
  window.addEventListener('booth-route',e=>{const entering=e.detail.active&&!active;active=e.detail.active;if(entering){showStep('layout');showInstructions()}if(!active){cancelCapture();stopCamera();if(dialog.open)dialog.close()}});
  window.addEventListener('pagehide',()=>{cancelCapture();stopCamera()});
  if(location.hash==='#booth'){active=true;showStep('layout');showInstructions()}
})();
